head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gLastJob = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // frame.width = 580;
        // frame.height = 240;

        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_Top);
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39003.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    // 파일업로드 데이터셋 초기화

    // dts_FileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_FileList.insertRow();
    rdo_mkt_tp_cd.setValue(js_market);
    if (js_market === "9") {
        rdo_mkt_tp_cd.setDisabled(false);
        rdo_mkt_tp_cd.addClass("TopCondition_Blue");
        txb_mkt_nm.hide();
    } else {
        // 콘트롤 잠그기
        // grd_Grid.ColumnProp("MKT_NM", "Show") = false;
        // rdo_mkt_tp_cd.Enable = false;
        rdo_mkt_tp_cd.hide();
        txb_mkt_nm.show("");
        if (rdo_mkt_tp_cd.getValue() === "1") {
            txb_mkt_nm.setValue("유가");
        } else if (rdo_mkt_tp_cd.getValue() === "2") {
            txb_mkt_nm.setValue("코스닥");
        } else if (rdo_mkt_tp_cd.getValue() === "6") {
            txb_mkt_nm.setValue("코넥스");
        }
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Save_onclick
 * @description 「파일업로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39003.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39003.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await scwin.alert_error2(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39003.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        const msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
        await $c.win.alert(msg);
        await $c.win.closePopup();
        $c.frame.path("../").fn_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39003.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name file_OnClick
 * @description file 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.file_OnClick = async function() {
    try {
        await scwin.selectAttach();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39003.file_OnClick" });
    }
};

/**
 * @method
 * @name btn_FORM_DOWN_onclick
 * @description 「샘플파일 다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_FORM_DOWN_onclick = function() {
    try {
        location.href = "/dsclmgt/outside_upload_sample.xls";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39003.btn_FORM_DOWN_onclick" });
    }
};

/**
 * @method
 * @name rdo_mkt_tp_cd_onselchange
 * @description rdo_mkt_tp_cd onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_mkt_tp_cd_onselchange = function() {
    // fn_SetCtrlByMktId();

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name save
 * @description 저장버튼 클릭 시
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    // dts_MASTER.AddRow();
    // dts_MASTER.NameValue(1,"MKT_TP_CD") =  getObjectValue(rdo_mkt_tp_cd);     //  js_market;        시장구분

    const mkt_tp_cd = rdo_mkt_tp_cd.getValue();
    let mkt_tp_nm = "";
    let confirmGbn = "";
    if (txb_FILE.getValue() === '') {
        await $c.win.alert("[첨부파일]을 선택하세요.");
        file.focus();
        return;
    }
    if (mkt_tp_cd === "1") {
        mkt_tp_nm = "유가";
    } else if (mkt_tp_cd === "2") {
        mkt_tp_nm = "코스닥";
    } else if (mkt_tp_cd === "6") {
        mkt_tp_nm = "코넥스";
    } else if (mkt_tp_cd === "9") {
        mkt_tp_nm = "전체";
    }
    if (js_market === "9") {
        confirmGbn = "시장구분이 '" + mkt_tp_nm + "' 입니다.\n기존 '" + mkt_tp_nm + "' 데이터가 삭제 된 후 첨부한 데이터가 업로드 됩니다.\n파일 업로드 하시겠습니까?";
    } else {
        confirmGbn = "기존 '" + mkt_tp_nm + "' 데이터가 삭제 된 후 첨부한 데이터가 업로드 됩니다.\n파일 업로드 하시겠습니까?";
    }
    if (confirm(confirmGbn)) {
        scwin.gLastJob = "파일 업로드";
        trs_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/OutDir.do",
            ref : "dts_MASTER,dts_FileList",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name alert_error2
 * @description 저장 에러 발생 시
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alert_error2 = async function(dtsObj) {
    const USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (let i = 0; i < USER_DEFINE.length; i++) {
        const errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        let j;
        for (j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) === '0') {
                // '0' 임의로 떨군 INFO 메시지
                await $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                // 기존 에러 메시지
                await $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};

/**
 * @method
 * @name selectAttach
 * @description 파일첨부 버튼 클릭 시
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectAttach = async function() {
    const vFile = file.getValue();
    if (vFile === "") {
        return;
    } else if (vFile.substring(vFile.length - 3, vFile.length).toUpperCase() !== "XLS") {
        await $c.win.alert("엑셀파일(*.xls)만 입력하시기 바랍니다.");
        txb_FILE.setValue("");
        return;
    } else {
        txb_FILE.setValue(file.getValue());
        dts_FileList.setCellData(1, "fileInfo", file.getValue());
        dts_FileList.setCellData(1, "fileUrl", file.getValue());
    }
};
